import { test } from "node:test";
import assert from "node:assert/strict";
import { invoiceSummary } from "../../src/invoice/index.ts";

test("invoice summary shows the pre-discount subtotal", () => {
  assert.equal(invoiceSummary([{ sku: "lamp", priceCents: 5000, qty: 3 }]), "Subtotal: $150.00");
  assert.equal(invoiceSummary([{ sku: "mug", priceCents: 1250, qty: 2 }]), "Subtotal: $25.00");
});
